from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
import requests
from .models import CSPViolationRecord

class ReplayCSPViolationWebhookView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, report_id):
        # Restrict report lookup to user's organization
        report = CSPViolationRecord.objects.filter(
            id=report_id,
            organization=request.user.organization
        ).first()
        if not report:
            return Response({"error": "Report not found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        # Use organization's preconfigured registered SIEM webhook, never arbitrary client URL
        configured_siem = request.user.organization.siem_webhook_url
        payload = {
            "document_uri": report.document_uri,
            "violated_directive": report.violated_directive,
            "blocked_uri": report.blocked_uri
        }
        requests.post(configured_siem, json=payload, timeout=5)
        return Response({"status": "Replayed to SIEM"}, status=status.HTTP_200_OK)
